// Normalize Kiwify and Hotmart webhook payloads into a standard format
const body = $input.first().json.body || $input.first().json;

// Detect platform
let platform = 'unknown';
let buyer = {};
let product = {};
let transaction = {};

// Kiwify format
if (body.order_status || body.customer) {
  platform = 'kiwify';
  buyer = {
    name: body.customer?.name || '',
    email: body.customer?.email || '',
    phone: body.customer?.mobile || body.customer?.phone || ''
  };
  product = {
    name: body.product?.name || '',
    id: body.product?.id || ''
  };
  transaction = {
    id: body.order_id || '',
    status: body.order_status || '',
    amount: body.amount || 0
  };
}
// Hotmart format
else if (body.data?.buyer || body.event) {
  platform = 'hotmart';
  const d = body.data || {};
  buyer = {
    name: d.buyer?.name || '',
    email: d.buyer?.email || '',
    phone: d.buyer?.phone || ''
  };
  product = {
    name: d.product?.name || '',
    id: d.product?.id || ''
  };
  transaction = {
    id: d.purchase?.transaction || '',
    status: body.event === 'PURCHASE_APPROVED' ? 'paid' : body.event,
    amount: d.purchase?.price?.value || 0
  };
}

// Only process paid purchases
if (!['paid', 'PURCHASE_APPROVED', 'approved', 'complete'].includes(transaction.status)) {
  return [{ json: { skip: true, reason: `Status: ${transaction.status}` } }];
}

return [{
  json: {
    platform,
    buyer,
    product,
    transaction,
    timestamp: new Date().toISOString()
  }
}];

